package r2dgit

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

const workloadOwnerLabel = "io.multica.git-supervisor"
const workloadNonceLabel = "io.multica.git-run"

var errWorkloadAbsent = errors.New("git_workload_absent")

// DockerWorkload is generated by the supervisor from operator policy. No task
// environment, arbitrary host mount, image, command or Docker option is accepted.
type DockerWorkload struct {
	Image      string
	User       string
	WorkingDir string
	Entrypoint []string
	Cmd        []string
	Env        []string
	Labels     map[string]string
	Volumes    map[string]struct{}
	HostConfig DockerWorkloadHost
}

type DockerWorkloadHost struct {
	NetworkMode     string
	PidMode         string
	IpcMode         string
	UTSMode         string
	UsernsMode      string
	CgroupnsMode    string
	Privileged      bool
	ReadonlyRootfs  bool
	CapDrop         []string
	CapAdd          []string
	SecurityOpt     []string
	Memory          int64
	MemorySwap      int64
	NanoCpus        int64
	PidsLimit       int64
	Binds           []string
	Tmpfs           map[string]string
	ExtraHosts      []string
	Links           []string
	VolumesFrom     []string
	GroupAdd        []string
	PublishAllPorts bool
	Devices         []json.RawMessage
	DeviceRequests  []json.RawMessage
	PortBindings    map[string]json.RawMessage
	RestartPolicy   struct{ Name string }
	LogConfig       struct{ Type string }
}

type DockerContainer struct {
	ID     string `json:"Id"`
	Names  []string
	Labels map[string]string
}

type DockerInspection struct {
	ID              string `json:"Id"`
	Name            string
	Config          DockerWorkload
	HostConfig      DockerWorkloadHost
	AppArmorProfile string
	Mounts          []DockerMount
	State           struct {
		Running  bool
		ExitCode int
	}
}

type DockerMount struct {
	Type, Source, Destination string
	RW                        bool
}

type WorkloadEngine interface {
	Create(context.Context, string, DockerWorkload) error
	Inspect(context.Context, string) (DockerInspection, error)
	Start(context.Context, string) error
	Remove(context.Context, string) error
	List(context.Context, string) ([]DockerContainer, error)
}

// DockerEngine speaks a fixed Engine API subset. The caller supplies a trusted
// transport (a Unix engine socket in deployment, fake HTTP in default tests).
// There is no ambient DOCKER_HOST, executable lookup or default client fallback.
type DockerEngine struct {
	Client   *http.Client
	Endpoint string
}

func (d DockerEngine) request(ctx context.Context, method, path string, input, output any) error {
	ctx, cancel := context.WithTimeout(ctx, time.Second)
	defer cancel()
	u, err := url.Parse(d.Endpoint)
	if err != nil || d.Client == nil || d.Client.Transport == nil || u.Scheme != "http" || u.Host == "" || u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" {
		return ErrRuntime
	}
	var body bytes.Buffer
	if input != nil {
		if err := json.NewEncoder(&body).Encode(input); err != nil {
			return err
		}
	}
	r, err := http.NewRequestWithContext(ctx, method, d.Endpoint+"/v1.47"+path, &body)
	if err != nil {
		return ErrRuntime
	}
	r.Header.Set("Content-Type", "application/json")
	// Never follow an engine redirect, even when the supplied client permits it.
	client := *d.Client
	client.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	resp, err := client.Do(r)
	if err != nil {
		return ErrRuntime
	}
	defer resp.Body.Close()
	if method == http.MethodDelete && resp.StatusCode == http.StatusNotFound {
		return nil
	}
	if method == http.MethodGet && resp.StatusCode == http.StatusNotFound {
		return errWorkloadAbsent
	}
	expected := http.StatusOK
	if method == http.MethodPost {
		expected = http.StatusCreated
		if strings.HasSuffix(path, "/start") {
			expected = http.StatusNoContent
		}
	}
	if method == http.MethodDelete {
		expected = http.StatusNoContent
	}
	if resp.StatusCode != expected {
		return fmt.Errorf("git_workload_engine_status_%d", resp.StatusCode)
	}
	if output == nil {
		return nil
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20+1))
	if err != nil || len(data) > 1<<20 {
		return ErrRuntime
	}
	if json.Unmarshal(data, output) != nil {
		return ErrRuntime
	}
	return nil
}

func dockerResource(name string) (string, error) {
	if len(name) == 64 && strings.Trim(name, "0123456789abcdef") == "" {
		return "/containers/" + name, nil
	}
	if len(name) > 180 || !strings.HasPrefix(name, "r2d-") {
		return "", ErrScope
	}
	for _, r := range name {
		if r != '-' && (r < 'a' || r > 'z') && (r < '0' || r > '9') {
			return "", ErrScope
		}
	}
	return "/containers/" + name, nil
}
func (d DockerEngine) Create(ctx context.Context, name string, spec DockerWorkload) error {
	if _, err := dockerResource(name); err != nil {
		return err
	}
	return d.request(ctx, http.MethodPost, "/containers/create?name="+url.QueryEscape(name), spec, nil)
}
func (d DockerEngine) Inspect(ctx context.Context, name string) (DockerInspection, error) {
	var out DockerInspection
	path, err := dockerResource(name)
	if err != nil {
		return out, err
	}
	err = d.request(ctx, http.MethodGet, path+"/json", nil, &out)
	return out, err
}
func (d DockerEngine) Start(ctx context.Context, name string) error {
	path, err := dockerResource(name)
	if err != nil {
		return err
	}
	return d.request(ctx, http.MethodPost, path+"/start", nil, nil)
}
func (d DockerEngine) Remove(ctx context.Context, name string) error {
	path, err := dockerResource(name)
	if err != nil {
		return err
	}
	return d.request(ctx, http.MethodDelete, path+"?force=true&v=true", nil, nil)
}
func (d DockerEngine) List(ctx context.Context, owner string) ([]DockerContainer, error) {
	filter, _ := json.Marshal(map[string][]string{"label": {workloadOwnerLabel + "=" + owner}})
	var out []DockerContainer
	err := d.request(ctx, http.MethodGet, "/containers/json?all=true&filters="+url.QueryEscape(string(filter)), nil, &out)
	return out, err
}
